// T0 geometry ledger — counts what a tree is made of and reports skeleton
// health. Reads the generator's own buffers (before the GLB writer); changes no
// generated byte.
//
// "Bitwise equal" positions: the three floats compare equal after memcpy to
// uint32_t (so -0.0 and 0.0 differ). The stall is recorded at skeleton level:
// `coincident_siblings_exact` is the stall count and the definition of a clean
// tree (zero). No mesh-level field finds every stalled tree.
#pragma once

#include "lod_emitter.hpp"
#include "skeleton.hpp"
#include "tree_descriptor.hpp"

#include <array>
#include <span>
#include <string>
#include <vector>

namespace treegen {

struct SkeletonLedger {
    int nodes                     = 0;
    int iterations_run            = 0;
    int max_iterations            = 0;  // descriptor
    int attractors_total          = 0;  // descriptor: branching.attractor_count
    int attractors_consumed       = 0;
    int coincident_siblings_exact = 0;  // nodes bitwise equal to an earlier sibling: the stall count
    int coincident_nodes_1mm      = 0;  // nodes whose lround(x*1000) triple matches an earlier node's (any parent)
    int largest_child_count       = 0;
    int largest_coincident_stack  = 1;  // most bitwise-equal siblings under one parent
    int near_sibling_pairs        = 0;  // sibling pairs closer than 0.25 * growth_distance, not bitwise equal
    int attractors_stalled        = 0;  // retired by the grower's stall guard (T1)
    int stall_side_branches       = 0;  // side branches the stall guard grew (T1)
    int near_pairs_side_vs_earlier = 0; // near pairs: a side branch and a sibling emitted before it (T1)
    int near_pairs_side_vs_later   = 0; // near pairs: a side branch and a later non-side sibling (T1)
};

// Indexed by BarkTriClass.
using BarkClassCounts = std::array<int, 4>;

// Diameter classes of 2 * node.radius: < 2 cm, 2-4, 4-8, 8-16, >= 16 cm.
constexpr int k_ledger_diameter_classes = 5;

struct LevelLedger {
    int bark_triangles = 0;
    int bark_vertices  = 0;
    BarkClassCounts by_class{};                                   // tube, tip, collar, crotch
    std::array<int, k_ledger_diameter_classes> tube_by_diameter{};
    std::array<int, k_ledger_diameter_classes> tip_by_diameter{};
    BarkClassCounts coincident_triangles{};                       // per class of the later triangle
    int open_edges        = 0;  // position-welded edges with exactly one bark triangle
    int nonmanifold_edges = 0;  // ... with more than two
    int degenerate_triangles = 0;  // triangles with two bitwise-equal corners (each distinct edge counts once)
    int    leaf_triangles  = 0;
    int    leaf_vertices   = 0;
    double leaf_card_area_m2 = 0.0;
    int    leaf_hosts      = 0;  // distinct bitwise leaf pivots
    int    leaf_max_vertices_on_one_host = 0;
    double leaf_distinct_position_ratio  = 0.0;  // distinct leaf positions / leaf vertices (0 without leaves)
};

struct TreeLedger {
    int                      schema = 1;
    SkeletonLedger           skeleton;
    std::vector<LevelLedger> levels;
};

SkeletonLedger compute_skeleton_ledger(const TreeDescriptor& desc, const TreeSkeleton& skel);
TreeLedger     compute_ledger(const TreeDescriptor& desc, const TreeSkeleton& skel,
                              std::span<const LodOutput> lods);

// Deterministic JSON (fixed key order, ints, doubles as %.17g).
std::string ledger_json(const TreeLedger& ledger);

}  // namespace treegen
